function counterUndo(commands) {
  let counter = 0;
  let stack = [];
  let result = [];
  for (let cmd of commands) {
    if (/^\+[-+]?\d+$/.test(cmd)) {
      counter += parseInt(cmd, 10);
      result.push(counter);
    } else if (cmd === 'save') {
      stack.push(counter);
      result.push(counter);
    } else if (cmd === 'undo' && stack.length > 0) {
      counter = stack.pop();
      result.push(counter);
    } else {
      result.push(counter);
    }
  }
  return result;
}
