```javascript
function lDecimalStep(s) {
  let arr = s.split('').map(c => parseInt(c));
  let i = arr.length - 1;
  while (i >= 0 && arr[i] === 0) {
    arr[i] = 9;
    i--;
  }
  if (i < 0) return '0';
  arr[i]--;
  if (arr[0] === 0 && arr.length > 1) {
    let j = 0;
    while (j < arr.length && arr[j] === 0) j++;
    arr = arr.slice(j);
  }
  return arr.join('');
}
