function lNestedMass(s) {
  let sum = 0, depth = 0;
  for (let c of s) {
    if (c === '(') depth++;
    else if (c === ')') depth--;
    else sum += parseInt(c) * Math.pow(2, depth);
  }
  return sum;
}
