function dashTokens(s) {
  const result = [];
  let current = '';
  let i = 0;
  while (i < s.length) {
    if (s[i] === '-' && i + 1 < s.length && s[i + 1] === '-') {
      current += '-';
      i += 2;
    } else if (s[i] === '-') {
      result.push(current);
      current = '';
      i++;
    } else {
      current += s[i];
      i++;
    }
  }
  result.push(current);
  return result;
}
