function foldParcel(s) {
  let stack = [];
  let result = '';
  let i = 0;
  while (i < s.length) {
    if (s[i] === '\\') {
      if (i + 1 < s.length) {
        result += s[++i];
      } else {
        return null;
      }
    } else if (s[i] === '(') {
      stack.push(result.length);
      result += '(';
    } else if (s[i] === ')') {
      if (stack.length === 0) return null;
      const start = stack.pop();
      const inner = result.slice(start + 1, result.length - 1);
      result = result.slice(0, start) + inner.split('').reverse().join('');
    } else {
      result += s[i];
    }
    i++;
  }
  if (stack.length > 0) return null;
  return result;
}
