```javascript
function roundTag(s, p) {
  let [intPart, fracPart] = s.split('.');
  if (intPart === '-0') intPart = '0';
  let num = intPart + fracPart.padEnd(5, '0');
  let rounded = num.slice(0, intPart.length + p + 1);
  let result = rounded.slice(0, intPart.length) + '.' + rounded.slice(intPart.length);
  return result.replace(/^0+\./, '0.').replace(/^-0\./, '0.');
}
```

```javascript
function roundTag(s, p) {
  let [intPart, decPart] = s.split('.');
  decPart = decPart.slice(0, p + 1);
  let num = parseFloat(intPart + '.' + decPart);
  let rounded = num.toFixed(p);
  return rounded.replace(/^0+(?=\d)/, '').replace(/\.0+$/, '');
}
