  if (nums.length === 0) return [];
  const bins = [];
  let currentBin = [nums[0]];
  let prevSign = nums[0] > 0 ? 1 : nums[0] < 0 ? -1 : 0;

  for (let i = 1; i < nums.length; i++) {
    const num = nums[i];
    if (num === 0) {
      currentBin.push(num);
      continue;
    }
    const currentSign = num > 0 ? 1 : -1;
    if (currentSign !== prevSign) {
      prevSign = currentSign;
      currentBin.push(num);
    } else {
      bins.push(currentBin);
      currentBin = [num];
      prevSign = currentSign;
    }
  }
  bins.push(currentBin);
  return bins;
}
