function checksumTiles(s) {
  let acc = 0;
  return s.split('').map(c => {
    if (/^[A-Za-z]$/.test(c)) {
      acc = 0;
      return c;
    } else {
      acc += parseInt(c, 10);
      return acc % 10;
    }
  }).join('');
}
