function mirrorKeys(obj) {
  const seen = new Set();
  const result = [];
  for (const key of Object.keys(obj)) {
    for (const value of obj[key]) {
      if (!seen.has(value)) {
        seen.add(value);
        result.push([value, [key]]);
      } else {
        result.find(r => r[0] === value)[1].push(key);
      }
    }
  }
  return result;
}
