```javascript
function noteLinks(edges, start) {
  const graph = {};
  for (const [from, to] of edges) {
    if (!graph[from]) graph[from] = new Set();
    graph[from].add(to);
  }

  const visited = new Set();
  const result = [];
  let current = start;

  while (current) {
    if (visited.has(current)) break;
    visited.add(current);
    result.push(current);

    const neighbors = graph[current] || new Set();
    if (neighbors.size !== 1) break;
    current = [...neighbors][0];
  }

  return result;
}
