function escapedPairs(s) {
  if (s === '') return [];
  const result = [];
  let i = 0, n = s.length;
  while (i < n) {
    let key = '', value = '';
    let escaped = false;
    while (i < n) {
      if (escaped) {
        key += s[i];
        escaped = false;
      } else if (s[i] === '\\') {
        escaped = true;
      } else if (s[i] === '=' && key === '') {
        break;
      } else if (s[i] === ',' && key !== '') {
        break;
      } else {
        key += s[i];
      }
      i++;
    }
    if (key === '' || (i < n && s[i] === ',')) {
      if (i < n && s[i] === ',') i++;
      result.push([key, value]);
    } else {
      return null;
    }
  }
  return result;
}
