function escapedPairs(s) {
  if (s === '') return [];
  const result = [];
  let i = 0;
  while (i < s.length) {
    if (s[i] === '\\') {
      if (i + 1 >= s.length) return null;
      i += 2;
    } else if (s[i] === ',') {
      i++;
    } else {
      let key = '';
      let value = '';
      let inKey = true;
      let escaped = false;
      while (i < s.length) {
        if (escaped) {
          key += s[i];
          escaped = false;
          i++;
        } else if (s[i] === '\\') {
          escaped = true;
          i++;
        } else if (s[i] === '=' && inKey) {
          inKey = false;
          i++;
        } else if (s[i] === ',' && !inKey) {
          i++;
          break;
        } else if (s[i] === ',' && inKey) {
          return null;
        } else {
          if (inKey) key += s[i];
          else value += s[i];
          i++;
        }
      }
      if (inKey) return null;
      result.push([key, value]);
    }
  }
  return result;
}
