function peakShelves(arr) {
  const result = [];
  for (let i = 0; i < arr.length; i++) {
    let j = i;
    while (j < arr.length && arr[j] === arr[i]) j++;
    const isPeak = (i === 0 || arr[i - 1] < arr[i]) && (j === arr.length || arr[j] < arr[i]);
    if (isPeak) result.push([i, j, arr[i]]);
    i = j - 1;
  }
  return result;
}
