```javascript
function cappedWalk(balance, low, high, deltas) {
  let final = balance;
  let spill = 0;
  for (const delta of deltas) {
    final += delta;
    if (final > high) {
      spill += final - high;
      final = high;
    } else if (final < low) {
      spill += final - low;
      final = low;
    }
  }
  return { final, spill };
}
```

