function nestDepths(s) {
  let depth = 0, maxDepth = 0, inQuote = false, escaped = false;
  for (let c of s) {
    if (escaped) {
      if (c === '\\' && inQuote) escaped = true;
      else escaped = false;
    } else if (c === "'") inQuote = !inQuote;
    else if (c === '[' && !inQuote) {
      depth++;
      maxDepth = Math.max(maxDepth, depth);
    } else if (c === ']' && !inQuote) {
      if (depth === 0) return null;
      depth--;
    } else if (c === '\\' && inQuote) escaped = true;
  }
  return inQuote || escaped ? null : maxDepth;
}
