function windowVotes(strings, windowSize) {
  const result = [];
  for (let i = 0; i <= strings.length - windowSize; i++) {
    const window = strings.slice(i, i + windowSize);
    const freq = {};
    let maxFreq = 0;
    let mostFrequent = '';
    for (let j = 0; j < windowSize; j++) {
      const str = window[j];
      freq[str] = (freq[str] || 0) + 1;
      if (freq[str] > maxFreq || (freq[str] === maxFreq && str > mostFrequent)) {
        maxFreq = freq[str];
        mostFrequent = str;
      }
    }
    result.push(mostFrequent);
  }
  return result;
}
