```javascript
function orderCrates(labels, dependencies) {
  const graph = {};
  const inDegree = {};
  const available = new Set(labels);

  labels.forEach(label => {
    graph[label] = new Set();
    inDegree[label] = 0;
  });

  dependencies.forEach(([before, after]) => {
    if (labels.includes(before) && labels.includes(after) && !graph[before].has(after)) {
      graph[before].add(after);
      inDegree[after]++;
    }
  });

  const result = [];
  while (available.size > 0) {
    const candidates = [...available].filter(label => inDegree[label] === 0);
    if (candidates.length === 0) return null;
    const next = candidates.sort()[0];
    result.push(next);
    available.delete(next);
    [...graph[next]].forEach(child => {
      inDegree[child]--;
    });
  }

  return result;
}
```

