function softWrap(words, width) {
  if (words.length === 0) return [];
  const result = [];
  let currentLine = [];
  let currentLength = 0;

  for (const word of words) {
    if (word.length > width) {
      if (currentLine.length > 0) {
        result.push(currentLine.join(' '));
        currentLine = [];
        currentLength = 0;
      }
      result.push(word);
    } else {
      const newLength = currentLength + (currentLine.length > 0 ? 1 + word.length : word.length);
      if (newLength > width) {
        result.push(currentLine.join(' '));
        currentLine = [word];
        currentLength = word.length;
      } else {
        currentLine.push(word);
        currentLength = newLength;
      }
    }
  }

  if (currentLine.length > 0) {
    result.push(currentLine.join(' '));
  }

  return result;
}
