function rowRotations(matrix, offsets) {
  return matrix.map((row, i) => {
    const offset = offsets[i] % row.length;
    return offset >= 0 ? [...row.slice(-offset), ...row.slice(0, -offset)] : [...row.slice(-offset), ...row.slice(0, -offset)];
  });
}
