function rebaseClock(time, delta) {
  const [h, m] = time.split(':').map(Number);
  const totalMinutes = h * 60 + m + delta;
  const days = Math.floor(totalMinutes / (24 * 60));
  const newMinutes = ((totalMinutes % (24 * 60)) + (24 * 60)) % (24 * 60);
  const newH = String(Math.floor(newMinutes / 60)).padStart(2, '0');
  const newM = String(newMinutes % 60).padStart(2, '0');
  return { time: `${newH}:${newM}`, days };
}
