function holeFill(arr) {
  const result = [...arr];
  const original = arr.map((v, i) => ({ val: v, idx: i })).filter(v => v.val !== null);
  for (let i = 0; i < result.length; i++) {
    if (result[i] === null) {
      let closest = original[0];
      for (let j = 1; j < original.length; j++) {
        if (Math.abs(i - original[j].idx) < Math.abs(i - closest.idx)) {
          closest = original[j];
        }
      }
      result[i] = closest.val;
    }
  }
  return result;
}
