  const original = arr.slice();
  for (let i = 0; i < original.length; i++) {
    if (original[i] === null) {
      let left = null;
      let right = null;
      for (let j = i - 1; j >= 0; j--) {
        if (original[j] !== null) {
          left = original[j];
          break;
        }
      }
      for (let j = i + 1; j < original.length; j++) {
        if (original[j] !== null) {
          right = original[j];
          break;
        }
      }
      if (left !== null && right !== null) {
        result[i] = left;
      } else if (left !== null) {
        result[i] = left;
      } else if (right !== null) {
        result[i] = right;
      }
    }
  }
  return result;
}
