function bracketTotals(s) {
  let i = 0;
  function parse() {
    let sum = 0;
    let depth = 1;
    while (i < s.length) {
      let c = s[i];
      if (c === ' ') { i++; continue; }
      if (c === ',') { i++; return sum; }
      if (c === '[') {
        i++; 
        const sub = parse();
        if (sub === null) return null;
        sum += sub * depth;
        if (s[i] !== ']') return null;
        i++;
        continue;
      }
      if (/[0-9\-]/.test(c)) {
        let num = 0, sign = 1;
        if (c === '-') { sign = -1; i++; c = s[i]; }
        while (i < s.length && /[0-9]/.test(s[i])) {
          num = num * 10 + parseInt(s[i], 10);
          i++;
        }
        sum += num * sign * depth;
        continue;
      }
      return null;
    }
    return sum;
  }
  const result = parse();
  if (i < s.length) return null;
  return result;
}
