  while (i < n) {
    if (s[i] === ' ') { i++; continue; }
    if (s[i] === '[') { stack.push(stack[stack.length - 1] + 1); i++; continue; }
    if (s[i] === ']') { stack.pop(); i++; continue; }
    if (s[i] === ',') { i++; continue; }
    if (/[+-]?\d/.test(s[i])) {
      let num = 0, sign = 1;
      if (s[i] === '-') { sign = -1; i++; }
      else if (s[i] === '+') i++;
      while (i < n && /\d/.test(s[i])) num = num * 10 + parseInt(s[i++], 10);
      total += sign * num * stack[stack.length - 1];
      continue;
    }
    return null;
  }
  return total;
}
