function batchCredits(events, lifetime) {
  const timeMap = new Map();
  const result = [];

  for (const [time, amount] of events) {
    if (!timeMap.has(time)) timeMap.set(time, 0);
    timeMap.set(time, timeMap.get(time) + amount);
  }

  const times = Array.from(timeMap.keys()).sort((a, b) => a - b);

  for (const time of times) {
    const total = Array.from(timeMap.entries()).reduce((sum, [t, amt]) => {
      if (t >= time && t < time + lifetime) return sum + amt;
      return sum;
    }, 0);
    result.push([time, total]);
  }

  return result;
}
