function batchCredits(events, lifetime) {
  const timeMap = new Map();
  for (const [time, amount] of events) {
    if (!timeMap.has(time)) timeMap.set(time, []);
    timeMap.get(time).push(amount);
  }
  const times = Array.from(timeMap.keys()).sort((a, b) => a - b);
  const result = [];
  let credits = new Map();
  let currentTotal = 0;

  for (const time of times) {
    // Expire old credits
    for (const [t, amounts] of credits) {
      if (t + lifetime <= time) {
        for (const amount of amounts) currentTotal += amount;
        credits.delete(t);
      }
    }

    // Add new events at this time
    const amounts = timeMap.get(time);
    for (const amount of amounts) {
      currentTotal += amount;
      if (!credits.has(time)) credits.set(time, []);
      credits.get(time).push(amount);
    }

    result.push([time, currentTotal]);
  }

  return result;
}
